    x.font = "400 " + Math.round(9.5 * sm) + "px " + MONO; x.globalAlpha = 0.6;
    x.fillText(key ? "SHEET 00 · ELEVATION, HALF IN SECTION · PLAN" : "SHEET " + String(LINE.indexOf(p) + 1).padStart(2, "0") + " / " + LINE.length + (s0.kind === "per" ? "" : " · " + p.name2.toUpperCase()), 8, 4 + Math.round(24 * sm));
